,"variety":"SL28, SL34, Ruiru 11, Batian","roast_for":"espresso","roaster_notes":["Prickly pear","peach","nougat"],"product_url":"https://www.fiveelephant.com/products/kenya-gondo-ab-espresso"},{"roaster_slug":"five-elephant","name":"COLOMBIA El Silencio Beer Hops – Filter","origin_country":"Kolumbien","region":"Buenavista, Quindío","producer":"Sara Gutiérrez (Finca El Silencio)","process":"Honey, mit Hopfen co-fermentiert","variety":"Caturra","roast_for":"filter","roaster_notes":["Lemon cake","kiwi","nutmeg"],"product_url":"https://www.fiveelephant.com/products/colombia-el-silencio-beer-filter"}]$seed$::jsonb) as x(roaster_slug text, name text, origin_country text, region text, producer text, process text, variety text, roast_for text, roaster_notes text[], product_url text)
join public.roasters r on r.slug = x.roaster_slug
where not exists (select 1 from public.coffees c where c.roaster_id = r.id and c.name_key = lower(regexp_replace(btrim(x.name), '\s+', ' ', 'g')) and c.merged_into is null);
commit;

