), updated as (
  update public.coffees c
  set photo_path = i.photo_path,
      product_url = coalesce(c.product_url, i.product_url)
  from images i
  where c.id = i.id::uuid
    and c.name = i.name
    and c.source = 'seed'
    and c.photo_path is null
  returning c.id
)
select count(*) as images_added from updated;
