), updated as (
  update public.coffees c
  set roast_level = case when c.roast_level_estimated or c.roast_level is null then r.roast_level else c.roast_level end,
      roast_level_estimated = case when c.roast_level_estimated or c.roast_level is null then r.estimated else c.roast_level_estimated end,
      recipe_dose_g = coalesce(c.recipe_dose_g, r.dose::numeric),
      recipe_yield_g = coalesce(c.recipe_yield_g, r.yield::numeric),
      recipe_time_s = coalesce(c.recipe_time_s, r.time_s::numeric),
      recipe_temp_c = coalesce(c.recipe_temp_c, r.temp::numeric)
  from r
  where (c.id = r.id::uuid or c.product_url = r.url) and c.name = r.name and c.source = 'seed'
  returning c.id
)
select count(*) as roast_levels_updated from updated;
-- END CATALOG ROAST LEVEL AND RECIPE
